def detect_duplicate(movement, others):
    """
    Detecta si un movimiento bancario es duplicado según criterios del motor:
    - Monto idéntico (crédito o débito)
    - Misma referencia o descripción muy similar
    - Misma fecha de transacción (del mismo período)
    Devuelve dict con isDuplicate=True, originalMovementId, confidence y reason en español.
    """
    for other in others:
        if other["id"] == movement["id"]:
            continue

        # Monto exactamente igual
        amount_match = False
        if movement["creditAmount"] is not None and other["creditAmount"] is not None:
            amount_match = abs(movement["creditAmount"] - other["creditAmount"]) < 0.01
        elif movement["debitAmount"] is not None and other["debitAmount"] is not None:
            amount_match = abs(movement["debitAmount"] - other["debitAmount"]) < 0.01
        elif movement["creditAmount"] is None and other["creditAmount"] is not None and movement["debitAmount"] is not None:
            amount_match = abs(movement["debitAmount"] - other["creditAmount"]) < 0.01
        elif movement["debitAmount"] is None and other["debitAmount"] is not None and movement["creditAmount"] is not None:
            amount_match = abs(movement["creditAmount"] - other["debitAmount"]) < 0.01

        if not amount_match:
            continue

        # Misma referencia
        reference_match = movement["reference"] == other["reference"]

        # Descripción muy similar (por defecto igual o similar con alta coincidencia)
        description_match = movement["description"] == other["description"]
        if not description_match:
            description_match = len(movement["description"].strip()) > len(other["description"].strip()) and \
                               movement["description"].startswith(other["description"]) or \
                               other["description"].startswith(movement["description"])

        if reference_match or description_match:
            return {
                "isDuplicate": True,
                "originalMovementId": other["id"],
                "confidence": 0.95 if reference_match else 0.85,
                "reason": "Monto igual y referencia exacta" if reference_match else "Monto igual y descripción muy similar"
            }

    return None

