def application_decision(amount, open_invoices, balance=None):
    """
    Decide how to apply a payment based on open invoices and a possible balance forward.

    Parameters
    ----------
    amount : float
        The payment amount.
    open_invoices : list[dict] | None
        List of open invoice dicts. Each dict may contain:
        - id
        - balance
        - dueDate
        - invoiceNumber
    balance : dict | None
        Customer balance forward, if any. Contains key 'amount'.

    Returns
    -------
    dict
        A decision dict with keys:
        - type: one of {advance, balance_forward, full, partial}
        - invoiceId: present for full/partial
        - details: Spanish explanation
    """
    # Helper to format money with two decimals
    def currency(value):
        return f"${round(value, 2)}"

    # No open invoices -> decide advance or balance forward
    if not open_invoices:
        if balance and balance.get('amount', 0) > 0:
            return {
                'type': 'balance_forward',
                'details': f'Saldo a favor actualizado: {currency(balance["amount"] + amount)}',
            }
        return {
            'type': 'advance',
            'details': f'No hay facturas abiertas. Monto registrado como anticipo: {currency(amount)}',
        }

    # Sort by dueDate ASC then by creation date ASC to get the oldest first (FIFO)
    sorted_invoices = sorted(
        open_invoices,
        key=lambda inv: (inv.get('dueDate', ''), inv.get('date', ''))
    )

    for inv in sorted_invoices:
        # Exact match
        if amount == inv.get('balance', 0):
            return {
                'type': 'full',
                'invoiceId': inv['id'],
                'details': f'Pago exacto de factura {inv["invoiceNumber"]}',
            }
        # Partial match (payment smaller than invoice balance)
        if amount < inv.get('balance', 0):
            remaining = inv.get('balance', 0) - amount
            return {
                'type': 'partial',
                'invoiceId': inv['id'],
                'details': f'Pago parcial de factura {inv["invoiceNumber"]}. Pendiente: {currency(remaining)}',
            }

    # Fallback: oldest open invoice (should rarely happen)
    oldest = sorted_invoices[0] if sorted_invoices else None
    if oldest:
        remaining = oldest.get('balance', 0) - amount if oldest.get('balance', 0) > amount else 0
        if remaining >= 0:
            return {
                'type': 'partial',
                'invoiceId': oldest['id'],
                'details': f'Pago parcial de factura {oldest["invoiceNumber"]}. Pendiente: {currency(remaining)}',
            }
    return {
        'type': 'advance',
        'details': 'No se identificó ninguna factura abierta que corresponda con el pago.',
    }
